"use client"

import { useEffect, useState, useRef } from "react"
import { motion, useInView } from "framer-motion"
import { Quote, ChevronLeft, ChevronRight, TrendingUp } from "lucide-react"

const metrics = [
  { value: 50000, suffix: "+", label: "Tonnes Collected", unit: "annually", icon: "📦" },
  { value: 120000, suffix: "+", label: "CO₂ Saved", unit: "kg reduced", icon: "🌱" },
  { value: 500, suffix: "+", label: "Green Jobs", unit: "created", icon: "💼" },
  { value: 25000, suffix: "+", label: "Trees Equivalent", unit: "preserved", icon: "🌳" },
]

const testimonials = [
  {
    quote:
      "Reverta transformed our corporate e-waste disposal process. Their data destruction certificate gave us complete peace of mind and compliance confidence.",
    author: "Priya Sharma",
    role: "IT Director",
    company: "TechCorp India",
  },
  {
    quote:
      "Exceptional service from initial pickup to final certification. The team is professional, punctual, and truly committed to environmental responsibility.",
    author: "Rahul Mehta",
    role: "Operations Manager",
    company: "GreenLeaf Ltd",
  },
  {
    quote:
      "A trusted partner for all our e-waste needs. Their transparent processes and detailed reporting have made sustainability simple for our organization.",
    author: "Anita Desai",
    role: "Sustainability Head",
    company: "EcoFirst Corp",
  },
]

function AnimatedCounter({ value, suffix = "" }: { value: number; suffix?: string }) {
  const [count, setCount] = useState(0)
  const ref = useRef(null)
  const isInView = useInView(ref, { once: true })

  useEffect(() => {
    if (isInView) {
      const duration = 2000
      const steps = 60
      const increment = value / steps
      let current = 0

      const timer = setInterval(() => {
        current += increment
        if (current >= value) {
          setCount(value)
          clearInterval(timer)
        } else {
          setCount(Math.floor(current))
        }
      }, duration / steps)

      return () => clearInterval(timer)
    }
  }, [isInView, value])

  return (
    <span ref={ref}>
      {count.toLocaleString()}
      {suffix}
    </span>
  )
}

export function Impact() {
  const [activeTestimonial, setActiveTestimonial] = useState(0)

  useEffect(() => {
    const interval = setInterval(() => {
      setActiveTestimonial((prev) => (prev + 1) % testimonials.length)
    }, 6000)
    return () => clearInterval(interval)
  }, [])

  const nextTestimonial = () => setActiveTestimonial((prev) => (prev + 1) % testimonials.length)
  const prevTestimonial = () => setActiveTestimonial((prev) => (prev - 1 + testimonials.length) % testimonials.length)

  return (
    <section
      id="impact"
      className="py-20 lg:py-32 bg-gradient-to-br from-primary via-primary/95 to-primary/90 text-primary-foreground relative overflow-hidden"
    >
      {/* Decorative elements */}
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-0 left-1/4 w-96 h-96 bg-white rounded-full blur-3xl" />
        <div className="absolute bottom-0 right-1/4 w-96 h-96 bg-white rounded-full blur-3xl" />
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center max-w-2xl mx-auto"
        >
          <div className="inline-flex items-center gap-2 bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full text-sm font-medium mb-6">
            <TrendingUp className="w-4 h-4" />
            Measurable Environmental Impact
          </div>
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-bold text-balance">Making a Real Difference</h2>
          <p className="mt-5 text-lg opacity-90 max-w-xl mx-auto">
            Every device recycled contributes to a cleaner, greener future for generations to come.
          </p>
        </motion.div>

        <div className="mt-16 grid grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
          {metrics.map((metric, index) => (
            <motion.div
              key={metric.label}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: index * 0.1 }}
              className="bg-white/10 backdrop-blur-sm rounded-2xl lg:rounded-3xl p-5 lg:p-8 text-center border border-white/10"
            >
              <p className="text-4xl sm:text-5xl lg:text-6xl font-bold tracking-tight">
                <AnimatedCounter value={metric.value} suffix={metric.suffix} />
              </p>
              <p className="mt-2 text-base lg:text-lg font-semibold">{metric.label}</p>
              <p className="text-sm opacity-70">{metric.unit}</p>
            </motion.div>
          ))}
        </div>

        <div className="mt-20 lg:mt-24">
          <motion.div
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
            className="relative max-w-4xl mx-auto"
          >
            {/* Testimonial card */}
            <div className="bg-white/10 backdrop-blur-sm rounded-3xl p-8 lg:p-12 border border-white/10">
              <Quote className="w-12 h-12 opacity-30 mb-6" />

              <div className="relative min-h-[180px] lg:min-h-[160px]">
                {testimonials.map((testimonial, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{
                      opacity: activeTestimonial === index ? 1 : 0,
                      y: activeTestimonial === index ? 0 : 20,
                    }}
                    transition={{ duration: 0.5 }}
                    className={`${activeTestimonial === index ? "relative" : "absolute inset-0"}`}
                    style={{ pointerEvents: activeTestimonial === index ? "auto" : "none" }}
                  >
                    <p className="text-xl lg:text-2xl font-medium leading-relaxed">"{testimonial.quote}"</p>
                    <div className="mt-8 flex items-center gap-4">
                      <div className="w-12 h-12 rounded-full bg-white/20 flex items-center justify-center font-bold text-lg">
                        {testimonial.author.charAt(0)}
                      </div>
                      <div>
                        <p className="font-semibold">{testimonial.author}</p>
                        <p className="text-sm opacity-80">
                          {testimonial.role}, {testimonial.company}
                        </p>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>

              {/* Navigation */}
              <div className="flex items-center justify-between mt-8 pt-6 border-t border-white/10">
                <div className="flex gap-2">
                  {testimonials.map((_, index) => (
                    <button
                      key={index}
                      onClick={() => setActiveTestimonial(index)}
                      className={`h-2 rounded-full transition-all duration-300 ${
                        activeTestimonial === index ? "bg-white w-8" : "bg-white/30 w-2 hover:bg-white/50"
                      }`}
                      aria-label={`Go to testimonial ${index + 1}`}
                    />
                  ))}
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={prevTestimonial}
                    className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center hover:bg-white/20 transition-colors"
                    aria-label="Previous testimonial"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </button>
                  <button
                    onClick={nextTestimonial}
                    className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center hover:bg-white/20 transition-colors"
                    aria-label="Next testimonial"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </button>
                </div>
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  )
}
